arguments.query:
SELECT time,pid,ppid,pname,process_name,command_line,access,object,event_record_id,event_id,source_stream,process_guid,parent_process_guid,parent_process_name,parent_process_path,parent_command_line,childproc_name,source_object_type,original_table,source_row_id
FROM audit_logs
WHERE (
    source_row_id IN ('1007854','996890','5113030','996906','1003480','5113280')
  )
ORDER BY time, source_row_id;
